/* Design 08: Retro-Industrial Audio
 * Recording studio control room palette. LED indicators as system state.
 * Dark charcoal backgrounds, lit by bright status lights.
 * oklch color space — functional and semantic colors.
 */

/* Dark theme (default) — "Night recording session" */
[data-design="8"],
[data-design="8"][data-theme="dark"] {
  /* Core palette — deep studio charcoal */
  --design-bg: oklch(0.12 0.008 250);
  --design-fg: oklch(0.92 0.01 90);
  --design-card: oklch(0.16 0.01 250);
  --design-card-fg: oklch(0.9 0.01 90);
  --design-primary: oklch(0.72 0.22 145);
  --design-primary-fg: oklch(0.1 0 0);
  --design-secondary: oklch(0.22 0.015 250);
  --design-secondary-fg: oklch(0.75 0.01 90);
  --design-muted: oklch(0.18 0.01 250);
  --design-muted-fg: oklch(0.55 0.01 90);
  --design-accent: oklch(0.72 0.22 145);
  --design-accent-fg: oklch(0.1 0 0);
  --design-destructive: oklch(0.62 0.24 27);
  --design-warning: oklch(0.78 0.18 85);
  --design-border: oklch(0.25 0.01 250);
  --design-input: oklch(0.14 0.008 250);
  --design-ring: oklch(0.72 0.22 145);
  --design-radius-sm: 0.125rem;
  --design-radius-md: 0.25rem;
  --design-radius-lg: 0.375rem;
  --design-radius-xl: 0.5rem;

  /* LED status indicators — the language of system state */
  --design-led-green: oklch(0.72 0.24 145);
  --design-led-amber: oklch(0.78 0.18 85);
  --design-led-red: oklch(0.62 0.26 27);
  --design-led-off: oklch(0.22 0.01 250);
  --design-led-glow-green: oklch(0.72 0.24 145 / 0.5);
  --design-led-glow-amber: oklch(0.78 0.18 85 / 0.5);
  --design-led-glow-red: oklch(0.62 0.26 27 / 0.5);

  /* LCD display styling — recessed dark panels */
  --design-lcd-bg: oklch(0.08 0.012 250);
  --design-lcd-text: oklch(0.72 0.22 145);
  --design-lcd-border: oklch(0.06 0.01 250);

  /* VU meter gradient segments */
  --design-vu-gradient-start: oklch(0.72 0.24 145);
  --design-vu-gradient-mid: oklch(0.78 0.18 85);
  --design-vu-gradient-end: oklch(0.62 0.26 27);

  /* Brushed metal and texture effects */
  --design-brushed-metal-light: oklch(0.35 0.01 250);
  --design-brushed-metal-dark: oklch(0.2 0.01 250);
  --design-scanline-color: oklch(0 0 0 / 0.03);
  --design-rack-grid-color: oklch(0.2 0.01 250 / 0.5);

  /* RECORD button specific */
  --design-record-bg: oklch(0.55 0.24 27);
  --design-record-hover: oklch(0.6 0.26 27);
  --design-record-active: oklch(0.65 0.28 27);
  --design-record-ring: oklch(0.55 0.24 27 / 0.4);
}

/* Light theme — "Daylight editing suite" */
[data-design="8"][data-theme="light"] {
  /* Core palette — bright studio white */
  --design-bg: oklch(0.97 0.005 90);
  --design-fg: oklch(0.15 0.02 250);
  --design-card: oklch(0.94 0.008 90);
  --design-card-fg: oklch(0.18 0.02 250);
  --design-primary: oklch(0.5 0.22 145);
  --design-primary-fg: oklch(0.98 0 0);
  --design-secondary: oklch(0.92 0.01 90);
  --design-secondary-fg: oklch(0.35 0.02 250);
  --design-muted: oklch(0.9 0.008 90);
  --design-muted-fg: oklch(0.5 0.015 250);
  --design-accent: oklch(0.5 0.22 145);
  --design-accent-fg: oklch(0.98 0 0);
  --design-destructive: oklch(0.55 0.24 27);
  --design-warning: oklch(0.7 0.2 85);
  --design-border: oklch(0.85 0.01 90);
  --design-input: oklch(0.95 0.005 90);
  --design-ring: oklch(0.5 0.22 145);
  --design-radius-sm: 0.125rem;
  --design-radius-md: 0.25rem;
  --design-radius-lg: 0.375rem;
  --design-radius-xl: 0.5rem;

  /* LED status indicators — still vibrant against white */
  --design-led-green: oklch(0.55 0.24 145);
  --design-led-amber: oklch(0.7 0.2 85);
  --design-led-red: oklch(0.55 0.26 27);
  --design-led-off: oklch(0.8 0.01 90);
  --design-led-glow-green: oklch(0.55 0.24 145 / 0.4);
  --design-led-glow-amber: oklch(0.7 0.2 85 / 0.4);
  --design-led-glow-red: oklch(0.55 0.26 27 / 0.4);

  /* LCD display styling — still recessed but lighter context */
  --design-lcd-bg: oklch(0.12 0.015 250);
  --design-lcd-text: oklch(0.72 0.22 145);
  --design-lcd-border: oklch(0.08 0.01 250);

  /* VU meter gradient segments */
  --design-vu-gradient-start: oklch(0.55 0.24 145);
  --design-vu-gradient-mid: oklch(0.7 0.2 85);
  --design-vu-gradient-end: oklch(0.55 0.26 27);

  /* Brushed metal and texture effects */
  --design-brushed-metal-light: oklch(0.88 0.01 90);
  --design-brushed-metal-dark: oklch(0.75 0.01 90);
  --design-scanline-color: oklch(0 0 0 / 0.02);
  --design-rack-grid-color: oklch(0.85 0.01 90 / 0.5);

  /* RECORD button specific */
  --design-record-bg: oklch(0.5 0.24 27);
  --design-record-hover: oklch(0.55 0.26 27);
  --design-record-active: oklch(0.6 0.28 27);
  --design-record-ring: oklch(0.5 0.24 27 / 0.3);
}

/* Selection styling */
[data-design="8"] ::selection {
  background: color-mix(in oklch, var(--design-led-green), transparent 70%);
  color: var(--design-fg);
}

/* Focus visible */
[data-design="8"] :focus-visible {
  outline: 1.5px solid var(--design-ring);
  outline-offset: 2px;
}

/* Scrollbar — industrial minimal */
[data-design="8"] ::-webkit-scrollbar {
  width: 6px;
}
[data-design="8"] ::-webkit-scrollbar-track {
  background: var(--design-bg);
}
[data-design="8"] ::-webkit-scrollbar-thumb {
  background: var(--design-border);
  border-radius: 3px;
}
[data-design="8"] ::-webkit-scrollbar-thumb:hover {
  background: var(--design-muted-fg);
}
[data-design="8"] {
  scrollbar-color: var(--design-border) var(--design-bg);
}

