  if (directPackagesMatch?.[1]) {
    return directPackagesMatch[1];
  }

  if (/(?:path\.)?(?:join|resolve)\([\s\S]*?['"`]src['"`]/.test(text)) {
    const segments = [...text.matchAll(/['"`]([^'"`]+)['"`]/g)].map(
