/**
 * Design System Token Contract Tests
 *
 * Validates that the web UI build output contains all required design system
 * tokens as defined by the imgen token-contract.css specification.
 *
 * These tests read from the built CSS output (packages/web-ui/build/),
 * not source files, ensuring the full Tailwind pipeline processes correctly.
 *
 * Spec: @ui-design-system
 */

import { describe, it, expect, beforeAll } from "vitest";
import { readdirSync, readFileSync, existsSync } from "node:fs";
import { join } from "node:path";

const WEB_UI_BUILD = join(
  process.cwd(),
  "packages",
  "web-ui",
  "build",
);
const CSS_ASSETS_DIR = join(WEB_UI_BUILD, "_app", "immutable", "assets");

let mainCss = "";

beforeAll(() => {
  if (!existsSync(CSS_ASSETS_DIR)) {
    throw new Error(
      `Build output not found at ${CSS_ASSETS_DIR}. Run "npm run build" in packages/web-ui/ first.`,
    );
  }

  const cssFiles = readdirSync(CSS_ASSETS_DIR).filter((f) =>
    f.endsWith(".css"),
  );
  mainCss = cssFiles
    .map((f) => readFileSync(join(CSS_ASSETS_DIR, f), "utf-8"))
    .join("\n");
});

// AC: @ui-design-system ac-1
describe("design system tokens (@ui-design-system ac-1)", () => {
  describe("16 color tokens mapped as Tailwind theme extensions", () => {
    const colorTokens = [
      "design-bg",
      "design-fg",
      "design-card",
      "design-card-fg",
      "design-primary",
      "design-primary-fg",
      "design-secondary",
      "design-secondary-fg",
      "design-muted",
      "design-muted-fg",
      "design-accent",
      "design-accent-fg",
      "design-destructive",
      "design-border",
      "design-input",
      "design-ring",
    ];

    it("includes all 16 design color token CSS custom properties", () => {
      for (const token of colorTokens) {
        expect(
          mainCss,
          `missing --design token: --${token}`,
        ).toContain(`--${token}`);
      }
    });

    it("maps all 16 design color tokens to Tailwind --color-* theme variables", () => {
      for (const token of colorTokens) {
        expect(
          mainCss,
          `missing Tailwind color mapping: --color-${token}`,
        ).toContain(`--color-${token}`);
      }
    });
  });

  describe("4 radius tokens", () => {
    const radiusTokens = [
      "design-radius-sm",
      "design-radius-md",
      "design-radius-lg",
      "design-radius-xl",
    ];

    it("includes all 4 design radius CSS custom properties", () => {
      for (const token of radiusTokens) {
        expect(
          mainCss,
          `missing --${token}`,
        ).toContain(`--${token}`);
      }
    });

    it("maps all 4 radii to Tailwind --radius-design-* theme variables", () => {
      for (const suffix of ["sm", "md", "lg", "xl"]) {
        expect(
          mainCss,
          `missing Tailwind radius mapping: --radius-design-${suffix}`,
        ).toContain(`--radius-design-${suffix}`);
      }
    });
  });

  describe("7 spacing tokens", () => {
    const spacingTokens = [
      "design-spacing-xs",
      "design-spacing-sm",
      "design-spacing-md",
      "design-spacing-lg",
      "design-spacing-xl",
      "design-spacing-2xl",
      "design-spacing-3xl",
    ];

    it("includes all 7 design spacing CSS custom properties", () => {
      for (const token of spacingTokens) {
        expect(
          mainCss,
          `missing --${token}`,
        ).toContain(`--${token}`);
      }
    });

    it("maps all 7 spacing tokens to Tailwind --spacing-design-* theme variables", () => {
      for (const suffix of ["xs", "sm", "md", "lg", "xl", "2xl", "3xl"]) {
        expect(
          mainCss,
          `missing Tailwind spacing mapping: --spacing-design-${suffix}`,
        ).toContain(`--spacing-design-${suffix}`);
      }
    });
  });

  describe("7 z-index layers", () => {
    const zIndexTokens = [
      "design-z-base",
      "design-z-dropdown",
      "design-z-sticky",
      "design-z-overlay",
      "design-z-modal",
      "design-z-popover",
      "design-z-toast",
    ];

    it("includes all 7 design z-index CSS custom properties", () => {
      for (const token of zIndexTokens) {
        expect(
          mainCss,
          `missing --${token}`,
        ).toContain(`--${token}`);
      }
    });

    it("maps all 7 z-index tokens to Tailwind --z-design-* theme variables", () => {
      for (const suffix of [
        "base",
        "dropdown",
        "sticky",
        "overlay",
        "modal",
        "popover",
        "toast",
      ]) {
        expect(
          mainCss,
          `missing Tailwind z-index mapping: --z-design-${suffix}`,
        ).toContain(`--z-design-${suffix}`);
      }
    });
  });

  describe("3 font families", () => {
    it("includes design font family CSS custom properties", () => {
      expect(mainCss).toContain("--font-design-primary");
      expect(mainCss).toContain("--font-design-secondary");
      expect(mainCss).toContain("--font-design-mono");
    });

    it("maps font families to Tailwind --font-* theme variables", () => {
      expect(mainCss).toContain("--font-design-sans");
      expect(mainCss).toContain("--font-design-heading");
    });
  });

  it("uses oklch color space for all design token values", () => {
    // Verify that the design tokens use oklch() color values
    expect(mainCss).toMatch(/--design-bg:\s*oklch\(/);
    expect(mainCss).toMatch(/--design-fg:\s*oklch\(/);
    expect(mainCss).toMatch(/--design-primary:\s*oklch\(/);
  });
});

// AC: @ui-design-system ac-2
describe("status colors and dark theme (@ui-design-system ac-2)", () => {
  const statusTokens = [
    "status-pending",
    "status-in-progress",
    "status-pending-review",
    "status-needs-work",
    "status-completed",
    "status-blocked",
    "status-cancelled",
  ];

  it("includes all 7 status color CSS custom properties with foreground variants", () => {
    for (const token of statusTokens) {
      expect(
        mainCss,
        `missing --design-${token}`,
      ).toContain(`--design-${token}`);
      expect(
        mainCss,
        `missing --design-${token}-fg`,
      ).toContain(`--design-${token}-fg`);
    }
  });

  it("maps all 7 status colors to Tailwind --color-status-* theme variables", () => {
    for (const token of statusTokens) {
      expect(
        mainCss,
        `missing Tailwind mapping: --color-${token}`,
      ).toContain(`--color-${token}`);
      expect(
        mainCss,
        `missing Tailwind mapping: --color-${token}-fg`,
      ).toContain(`--color-${token}-fg`);
    }
  });

  it("uses oklch color space for status tokens", () => {
    expect(mainCss).toMatch(/--design-status-pending:\s*oklch\(/);
    expect(mainCss).toMatch(/--design-status-completed:\s*oklch\(/);
    expect(mainCss).toMatch(/--design-status-blocked:\s*oklch\(/);
  });

  it("includes dark theme overrides for status colors", () => {
    // The .dark selector should contain status color overrides
    // In minified CSS this appears as .dark{...--design-status-...}
    expect(mainCss).toMatch(/\.dark\b/);
    // Dark theme should have different status values
    // Count occurrences — we expect at least 2 sets (light + dark)
    const pendingCount = (
      mainCss.match(/--design-status-pending:/g) || []
    ).length;
    expect(
      pendingCount,
      "status-pending should appear in both :root and .dark",
    ).toBeGreaterThanOrEqual(2);
  });

  it("status colors map to distinct oklch hues", () => {
    // Extract oklch values for each status to verify they're distinct
    // pending=amber (~85 hue), in_progress=orange (~48 hue),
    // pending_review=blue (~259 hue), needs_work=yellow (~92 hue),
    // completed=emerald (~156 hue), blocked=red (~27 hue), cancelled=gray (low chroma)
    const huePattern = /--design-status-(\w[\w-]*):\s*oklch\([^)]+\)/g;
    const matches = [...mainCss.matchAll(huePattern)];
    const statusNames = new Set(matches.map((m) => m[1].replace(/-fg$/, "")));

    // All 7 statuses must be present
    expect(statusNames.size).toBeGreaterThanOrEqual(7);
  });
});

// AC: @ui-design-system ac-3
describe("shimmer animation (@ui-design-system ac-3)", () => {
  it("defines ds-shimmer keyframes", () => {
    expect(mainCss).toContain("ds-shimmer");
  });

  it("includes the .ds-shimmer utility class", () => {
    expect(mainCss).toContain("ds-shimmer");
  });

  it("gates shimmer animation behind prefers-reduced-motion", () => {
    expect(mainCss).toContain("prefers-reduced-motion");
  });

  it("registers ds-shimmer as a Tailwind animation token", () => {
    expect(mainCss).toContain("--animate-ds-shimmer");
  });
});

// AC: @ui-design-system ac-4
describe("breathing/pulse animation (@ui-design-system ac-4)", () => {
  it("defines ds-breathe keyframes", () => {
    expect(mainCss).toContain("ds-breathe");
  });

  it("includes the .ds-breathe utility class", () => {
    expect(mainCss).toContain("ds-breathe");
  });

  it("gates breathing animation behind prefers-reduced-motion", () => {
    // Both ds-shimmer and ds-breathe should be gated
    // The reduced-motion media query should disable both
    expect(mainCss).toContain("prefers-reduced-motion");
  });

  it("registers ds-breathe as a Tailwind animation token", () => {
    expect(mainCss).toContain("--animate-ds-breathe");
  });
});

